#include "mlmw_test.h"
#include "mlmw/lin.h"
#include <string.h>

ZTEST(agent_lin, test_mlmw_lin_pid)
{
	uint8_t id = 0x24u;
	uint8_t expected_pid = 0x24u | (0x01u << 6) | (0x00u << 7);
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_EQ(pid, expected_pid);
}

ZTEST(agent_lin, test_mlmw_lin_pid_invalid)
{
	uint8_t id = 0x3Fu;
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_FALSE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_pid_valid)
{
	uint8_t id = 0x24u;
	uint8_t pid = mlmw_lin_pid(id);
	EXPEC_TRUE(mlmw_lin_pid_valid(pid));
}

ZTEST(agent_lin, test_mlmw_lin_checksum_classic)
{
	uint8_t pid = 0x3Cu;
	uint8_t data[] = {0x01u, 0x02u, 0x03u};
	uint8_t expected_checksum = 0x00u;
	uint8_t checksum = mlmw_lin_checksum(pid, data, sizeof(data), false);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_enhanced)
{
	uint8_t pid = 0x24u;
	uint8_t data[] = {0x01u, 0x02u, 0x03u};
	uint8_t expected_checksum = 0x04u;
	uint8_t checksum = mlmw_lin_checksum(pid, data, sizeof(data), true);
	EXPEC_EQ(checksum, expected_checksum);
}

ZTEST(agent_lin, test_mlmw_lin_checksum_enhanced_diagnostic)
{
	uint8_t pid = 0x3Cu;
	uint8_t data[] = {0x01u, 0x02u, 0x03u};
	uint8_t expected_checksum = 0x00u;
